{"source":"#!/usr/bin/env python3.12
"""Summarize a UTF-8 CSV (header: category,amount,status) into paid-only totals."""
import csv
import json
import re
import sys
from decimal import Decimal, ROUND_HALF_UP

TWO = Decimal("0.01")


def normalize_category(raw: str) -> str:
    collapsed = re.sub(r"\s+", " ", raw).strip()
    collapsed = collapsed.casefold()
    return collapsed if collapsed else "uncategorized"


def round2(value: Decimal) -> Decimal:
    return value.quantize(TWO, rounding=ROUND_HALF_UP)


def main(argv) -> int:
    if len(argv) < 2:
        sys.stderr.write("usage: solution.py <input.csv>\n")
        return 2

    with open(argv[1], "r", encoding="utf-8", newline="") as fh:
        reader = csv.DictReader(fh)
        # Preserve input bytes: do not write to the input file.
        totals: dict[str, Decimal] = {}
        grand_total = Decimal("0")

        for row in reader:
            status = (row.get("status") or "").strip().casefold()
            if status != "paid":
                continue

            category = normalize_category(row.get("category") or "")
            amount = round2(Decimal((row.get("amount") or "").strip()))

            totals[category] = totals.get(category, Decimal("0")) + amount
            grand_total += amount

    categories = [
        {"category": name, "total": format2(totals[name])}
        for name in sorted(totals)
    ]
    result = {"categories": categories, "total": format2(grand_total)}
    sys.stdout.write(json.dumps(result))
    return 0


def format2(value: Decimal) -> str:
    return str(round2(value + Decimal("0")))


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))"}

